  if(!List.of("TEV1","RANDOM","EXPLORER").contains(p.player()))throw new BadRequestException("Unknown player");
  int limit=p.maxDecisions()==null?128:p.maxDecisions();long millis=p.durationMs()==null?120000:p.durationMs();if(limit<1||limit>128||millis<1||millis>120000)throw new BadRequestException("Budget exceeds demo bounds");
  RunState r=admit(p.player(),"",p.revision(),limit,millis);
  execute(r).subscribe().with(done->{},error->{});return view();
 }
 @POST @Path("/pause") public Map<String,Object> pause(){session.pause();return view();}
 @GET @Path("/history") public List<ActionLog> history(){return session.history();}
 @GET @Path("/events") @Produces(MediaType.SERVER_SENT_EVENTS) @RestStreamElementType(MediaType.APPLICATION_JSON)
 public Multi<Map<String,Object>> events(){return Multi.createFrom().ticks().every(Duration.ofMillis(150)).onOverflow().drop().map(t->view());}
 private RunState admit(String player,String action,long revision,int limit,long duration){try{return session.admit(player,action,revision,limit,duration);}catch(IllegalArgumentException|IllegalStateException e){throw new ClientErrorException(e.getMessage(),409);}}
 /** This is the sole external root-admission boundary. Internal turns never re-enter it. */
 private Uni<RunResult> execute(RunState r){
  String execution=UUID.randomUUID().toString();
  PipelineExecutionContextHolder.set(new PipelineExecutionContext("local-demo",execution,0));
  try {
   return pipelines.<RunResult>executePipelineUnary(Uni.createFrom().item(r))
    .ifNoItem().after(Duration.ofMillis(Math.max(1,(r.deadline()-System.nanoTime())/1_000_000))).fail()
    .invoke(result->session.finish(r.segment(),result.reason()))
    .onFailure().invoke(failure->session.finish(r.segment(),"PROVIDER_OR_PIPELINE_FAILURE: "+failure.getClass().getSimpleName()));
  }finally{PipelineExecutionContextHolder.clear();}
 }
}
